import java.util.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Read input
        long x = sc.nextLong();
        long y = sc.nextLong();
        int n = sc.nextInt();

        // Compute gcd
        long g = gcd(x, y);
        x /= g;
        y /= g;

        long q = x / y;
        long r = x % y;

        // Map to store results: key is ratio (as Double), value is a TreeSet of pairs
        TreeMap<Double, TreeSet<Pair>> result = new TreeMap<>();

        // Helper function to compute gcd
        // (In Java, define as static method below)

        // Save ratio function
        class Saver {
            void saveRatio(long a, long b, long u, long z, long t) {
                long g2 = gcd(a, b);
                double ratio = Math.abs((double)(a - u * z) / t);
                result.computeIfAbsent(ratio, k -> new TreeSet<>()).add(new Pair(b / g2, a / g2));
            }
        }

        Saver saver = new Saver();

        for (long b = 1; b <= n; b++) {
            g = gcd(y, b);
            long c = b / g;
            long z = y / g;
            long t = b * z;
            long u = q * t + r * c;

            // Save first ratio
            saver.saveRatio(u, z, u, z, t);

            // Save second ratio if u % z != 0
            if (u % z != 0) {
                long u2 = (u + z - 1) / z;
                saver.saveRatio(u2, z, u, z, t);
            }
        }

        // Get the first element in the result map
        Map.Entry<Double, TreeSet<Pair>> firstEntry = result.firstEntry();
        Pair p = firstEntry.getValue().first();

        System.out.println(p.second + "/" + p.first);
    }

    static long gcd(long a, long b) {
        return BigInteger.valueOf(a).gcd(BigInteger.valueOf(b)).longValue();
    }

    static class Pair implements Comparable<Pair> {
        long first, second;

        Pair(long first, long second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int compareTo(Pair o) {
            if (this.second != o.second) {
                return Long.compare(this.second, o.second);
            }
            return Long.compare(this.first, o.first);
        }
    }
}
